import { render, type RenderOptions } from "@testing-library/react";
import axe from "axe-core";
import type { ReactElement } from "react";
import { expect } from "vitest";

export function renderWithProviders(
  ui: ReactElement,
  options?: Omit<RenderOptions, "wrapper">,
) {
  return render(ui, options);
}

export async function expectNoA11yViolations(container: HTMLElement) {
  const results = await axe.run(container, {
    rules: {
      "color-contrast": { enabled: false },
    },
  });

  const criticalViolations = results.violations.filter(
    (violation) => violation.impact === "critical",
  );

  expect(criticalViolations).toEqual([]);
}

export * from "@testing-library/react";

export type SectionId =
  | "home"
  | "about"
  | "activities"
  | "services"
  | "help"
  | "contact";

export type NavigationLink = {
  id: SectionId;
  label: string;
  href: `#${SectionId}`;
};

import type { NavigationLink } from "@/types/navigation";

export type FooterContent = {
  brandDescription: string;
  contactHeading: string;
  address: string;
  phones: string[];
  email: string;
  quickLinksHeading: string;
  quickLinks: NavigationLink[];
  copyrightLabel: string;
};

const LANDING_TIME_ZONE = "Asia/Ho_Chi_Minh";

type DateParts = {
  day: string;
  month: string;
  year: string;
  hour: string;
  minute: string;
};

function getParts(value: Date): DateParts | null {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) {
    return null;
  }

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: LANDING_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(value);

  const get = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((part) => part.type === type)?.value ?? "";

  return {
    day: get("day"),
    month: get("month"),
    year: get("year"),
    hour: get("hour"),
    minute: get("minute"),
  };
}

function toDate(parts: DateParts): string {
  return `${parts.day}/${parts.month}/${parts.year}`;
}

function toTime(parts: DateParts): string {
  return `${Number(parts.hour)}:${parts.minute}`;
}

export function formatActivityTime(start: Date, end: Date): string {
  const startParts = getParts(start);
  const endParts = getParts(end);

  if (!startParts || !endParts) {
    return "Invalid date";
  }

  const sameDay =
    startParts.day === endParts.day &&
    startParts.month === endParts.month &&
    startParts.year === endParts.year;

  if (sameDay) {
    return `${toDate(startParts)}, ${toTime(startParts)} - ${toTime(endParts)}`;
  }

  return `${toDate(startParts)} ${toTime(startParts)} - ${toDate(endParts)} ${toTime(endParts)}`;
}

export type DataSource = "mock" | "api";

export function getDataSource(): DataSource {
  return process.env.NEXT_PUBLIC_DATA_SOURCE === "api" ? "api" : "mock";
}

export function isMockDataSource(): boolean {
  return getDataSource() === "mock";
}

import { ROLE_CODES, RoleCode } from "@/libs/roles";

// for side bar items
export const NAVIGATION_ITEMS: Record<
  RoleCode,
  { label: string; href: string }[]
> = {
  student: [
    { label: "Dashboard", href: "/student/dashboard" },
    { label: "Activities", href: "/student/activities" },
  ],
  organizer: [{ label: "Dashboard", href: "/organizer/dashboard" }],
  admin: [{ label: "Dashboard", href: "/admin/dashboard" }],
};

export function getDashboardPath(role?: RoleCode | null): string {
  if (!role || !ROLE_CODES.includes(role)) {
    return "/login";
  }

  return (
    NAVIGATION_ITEMS[role].find((item) => item.label === "Dashboard")?.href ??
    "/login"
  );
}

export function isSafeRedirectPath(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0) {
    return false;
  }

  if (!value.startsWith("/") || value.startsWith("//")) {
    return false;
  }

  if (value.includes("\\") || /[\u0000-\u001f\u007f]/.test(value)) {
    return false;
  }

  try {
    const url = new URL(value, "https://myhcmus.local");

    if (url.origin !== "https://myhcmus.local") {
      return false;
    }

    if (url.pathname === "/login" || url.pathname.startsWith("/login/")) {
      return false;
    }

    return true;
  } catch {
    return false;
  }
}

export function getLoginHref(returnTo?: string): string {
  if (!returnTo || !isSafeRedirectPath(returnTo)) {
    return "/login";
  }

  return `/login?redirectTo=${encodeURIComponent(returnTo)}`;
}

