@import "tailwindcss";

:root {
  color-scheme: light;
  --background: #ffffff;
  --foreground: #111827;
}

@theme {
  --color-primary: #1f4fa3;
  --color-primary-dark: #17409a;
  --color-accent-gold: #f2b31b;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-surface: #ffffff;
  --color-success: #16a34a;
  --color-warning: #d97706;
  --color-neutral-status: #6b7280;
  --color-guide-gradient-from: #ffffff;
  --color-guide-gradient-to: #e3eefb;
  --color-focus-ring: #f2b31b;
  --radius-card: 24px;
  --radius-pill: 9999px;
  --shadow-card: 0 8px 24px rgba(0, 0, 0, 0.1);
  --container-landing: 1200px;
  --header-height: 56px;
  --page-gutter: 24px;
  --focus-ring-width: 3px;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), Arial, Helvetica, sans-serif;
}

:focus-visible {
  outline: var(--focus-ring-width) solid var(--color-focus-ring);
  outline-offset: 3px;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

