"use client";

import { AuthContext } from "@/features/auth/context/AuthContext";
import { mockAuthService } from "@/features/auth/services/mock.auth.service";
import { SessionUser } from "@/features/auth/types/auth";
import { LoginRequest } from "@/features/auth/types/auth.dto";
import { useState, useCallback, useEffect, useMemo } from "react";

interface AuthProviderProps {
  children: React.ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<SessionUser | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const authServiceInstance = mockAuthService;
  const removeUser = useCallback(async () => {
    setUser(null);
  }, []);

  const login = useCallback(
    async (data: LoginRequest) => {
      try {
        setIsLoading(true);
        const response = await authServiceInstance.login(data);
        if (response.user != null) {
          setUser(response.user);
          return response.user;
        }
        throw new Error("Login failed: user is null");
      } catch (error) {
        await removeUser();
        console.error("Login failed", error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [authServiceInstance, removeUser],
  );

  const logout = useCallback(async () => {
    try {
      setIsLoading(true);
      await authServiceInstance.logout();
      await removeUser();
    } catch (error) {
      console.error("Logout failed", error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [authServiceInstance, removeUser]);

  const refreshUser = useCallback(async () => {
    try {
      setIsLoading(true);
      const response = await authServiceInstance.getMe();
      if (response) {
        setUser(response);
      }
    } catch (error) {
      await removeUser();
      console.error("Refresh user failed", error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [authServiceInstance, removeUser]);

  useEffect(() => {
    const initializeUser = async () => {
      try {
        await refreshUser();
      } catch (error) {
        console.error("Failed to initialize user", error);
      }
    };

    void initializeUser();
  }, [refreshUser]);

  const value = useMemo(
    () => ({
      user,
      isAuthenticated: user !== null,
      login,
      logout,
      refreshUser,
      isLoading,
    }),
    [user, login, logout, refreshUser, isLoading],
  );

  return (
    <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
  );
}

import type {
  AuthResponse,
  LoginRequest,
} from "@/features/auth/types/auth.dto";
import type {
  SessionUser,
  StaffSessionUser,
  StudentSessionUser,
} from "@/features/auth/types";
import { ROLE_CODES } from "@/libs/roles";

type MockAuthScenario = "guest" | "student" | "organizer" | "admin";

function getScenario(): MockAuthScenario {
  const value = process.env.NEXT_PUBLIC_MOCK_AUTH_STATE;

  if (value === "guest" || value === "organizer" || value === "admin") {
    return value;
  }

  return "student";
}

function createUser(scenario: Exclude<MockAuthScenario, "guest">): SessionUser {
  if (scenario === "student") {
    const user: StudentSessionUser = {
      studentNumber: "123456789",
      email: "khangthinh111555@gmail.com",
      role: "student",
      facultyId: 1,
      fullName: "Khang Thinh",
      avatarUrl: null,
      userId: 1,
      permissions: [],
    };

    return user;
  }

  const user: StaffSessionUser = {
    userId: scenario === "organizer" ? 2 : 3,
    email: `${scenario}@hcmus.edu.vn`,
    fullName: scenario === "organizer" ? "Mock Organizer" : "Mock Admin",
    role: scenario,
    permissions: [],
    studentNumber: null,
    facultyId: null,
    avatarUrl: null,
  };

  return user;
}

class MockAuthService {
  async login(data: LoginRequest): Promise<AuthResponse> {
    await new Promise((resolve) => setTimeout(resolve, 300));

    if (
      data.role === ROLE_CODES[0] &&
      data.email === "khangthinh111555@gmail.com" &&
      data.password === "123456"
    ) {
      return { user: createUser("student") };
    }

    throw new Error("Invalid email or password or role");
  }

  async logout(): Promise<void> {
    return;
  }

  async getMe(): Promise<SessionUser> {
    await new Promise((resolve) => setTimeout(resolve, 150));
    const scenario = getScenario();

    if (scenario === "guest") {
      throw new Error("No active mock session");
    }

    return createUser(scenario);
  }
}

export const mockAuthService = new MockAuthService();

import { describe, expect, it } from "vitest";
import { formatActivityTime } from "./format";

describe("formatActivityTime", () => {
  it("formats a same-day activity", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T08:00:00+07:00"),
        new Date("2026-10-17T10:00:00+07:00"),
      ),
    ).toBe("17/10/2026, 8:00 - 10:00");
  });

  it("formats a multi-day activity with both dates", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T08:00:00+07:00"),
        new Date("2026-10-18T10:00:00+07:00"),
      ),
    ).toBe("17/10/2026 8:00 - 18/10/2026 10:00");
  });

  it("formats midnight without a leading hour zero", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T00:05:00+07:00"),
        new Date("2026-10-17T00:30:00+07:00"),
      ),
    ).toBe("17/10/2026, 0:05 - 0:30");
  });

  it("keeps two-digit minutes", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T09:05:00+07:00"),
        new Date("2026-10-17T09:07:00+07:00"),
      ),
    ).toBe("17/10/2026, 9:05 - 9:07");
  });

  it("uses the Asia/Ho_Chi_Minh timezone at the UTC boundary", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-16T17:00:00Z"),
        new Date("2026-10-16T19:00:00Z"),
      ),
    ).toBe("17/10/2026, 0:00 - 2:00");
  });

  it("renders a safe fallback for invalid dates", () => {
    expect(formatActivityTime(new Date("invalid"), new Date())).toBe(
      "Invalid date",
    );
  });
});

import { describe, expect, it } from "vitest";
import {
  getDashboardPath,
  getLoginHref,
  isSafeRedirectPath,
} from "./navigation";

describe("navigation helpers", () => {
  it("resolves a dashboard path for every role", () => {
    expect(getDashboardPath("student")).toBe("/student/dashboard");
    expect(getDashboardPath("organizer")).toBe("/organizer/dashboard");
    expect(getDashboardPath("admin")).toBe("/admin/dashboard");
    expect(getDashboardPath(null)).toBe("/login");
  });

  it("encodes a valid landing return path", () => {
    expect(getLoginHref("/#services")).toBe(
      "/login?redirectTo=%2F%23services",
    );
    expect(getLoginHref()).toBe("/login");
  });

  it("accepts safe same-origin landing paths", () => {
    expect(isSafeRedirectPath("/")).toBe(true);
    expect(isSafeRedirectPath("/#services")).toBe(true);
    expect(isSafeRedirectPath("/activities/abc?tab=details")).toBe(true);
  });

  it("rejects unsafe redirect targets", () => {
    expect(isSafeRedirectPath("https://evil.example")).toBe(false);
    expect(isSafeRedirectPath("//evil.example")).toBe(false);
    expect(isSafeRedirectPath("/\\evil.example")).toBe(false);
    expect(isSafeRedirectPath("/\nservices")).toBe(false);
    expect(isSafeRedirectPath("/login")).toBe(false);
    expect(isSafeRedirectPath("/login?redirectTo=%2Fservices")).toBe(false);
    expect(isSafeRedirectPath("services")).toBe(false);
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import { api } from "./api-client";

describe("api client", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("forwards an abort signal to fetch and returns parsed JSON", async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      new Response(JSON.stringify({ data: { ok: true } }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    );
    vi.stubGlobal("fetch", fetchMock);
    const controller = new AbortController();

    const result = await api.get<{ data: { ok: boolean } }>(
      "/activities/landing",
      { signal: controller.signal },
    );

    expect(result).toEqual({ data: { ok: true } });
    expect(fetchMock).toHaveBeenCalledWith(
      expect.stringContaining("/activities/landing"),
      expect.objectContaining({ signal: controller.signal }),
    );
  });

  it("normalizes non-ok responses into an Error", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue(
        new Response("server exploded", {
          status: 500,
          statusText: "Internal Server Error",
        }),
      ),
    );

    await expect(api.get("/activities/landing")).rejects.toThrow(
      "API request failed: 500 Internal Server Error - server exploded",
    );
  });
});

export function cn(...classes: Array<string | false | null | undefined>): string {
  return classes.filter(Boolean).join(" ");
}

import Link from "next/link";
import type { ButtonHTMLAttributes, ReactNode } from "react";
import { cn } from "@/libs/cn";

type ButtonVariant = "primary" | "secondary" | "white" | "ghost";
type ButtonSize = "sm" | "md" | "lg";

type ButtonProps = {
  variant?: ButtonVariant;
  size?: ButtonSize;
  href?: string;
  isLoading?: boolean;
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
  children: ReactNode;
  className?: string;
  target?: string;
  rel?: string;
} & Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "className">;

const variantClasses: Record<ButtonVariant, string> = {
  primary:
    "bg-primary text-white shadow-sm hover:bg-primary-dark disabled:hover:bg-primary",
  secondary:
    "bg-primary-dark text-white shadow-sm hover:bg-primary disabled:hover:bg-primary-dark",
  white:
    "bg-surface text-primary shadow-card hover:bg-guide-gradient-to disabled:hover:bg-surface",
  ghost:
    "bg-transparent text-text hover:bg-black/5 disabled:hover:bg-transparent",
};

const sizeClasses: Record<ButtonSize, string> = {
  sm: "min-h-11 px-5 text-sm",
  md: "min-h-11 px-6 text-sm",
  lg: "min-h-12 px-8 text-base",
};

export function Button({
  variant = "primary",
  size = "md",
  href,
  isLoading = false,
  leftIcon,
  rightIcon,
  children,
  className,
  target,
  rel,
  disabled,
  type = "button",
  ...rest
}: ButtonProps) {
  const isDisabled = Boolean(disabled) || isLoading;
  const classes = cn(
    "inline-flex min-w-11 items-center justify-center gap-2 rounded-pill font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring disabled:cursor-not-allowed disabled:opacity-55",
    variantClasses[variant],
    sizeClasses[size],
    className,
  );

  const content = (
    <>
      {isLoading ? (
        <span
          aria-hidden="true"
          className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent motion-reduce:animate-none"
        />
      ) : (
        leftIcon
      )}
      <span>{children}</span>
      {!isLoading && rightIcon}
    </>
  );

  if (href && !isDisabled) {
    return (
      <Link
        href={href}
        className={classes}
        target={target}
        rel={rel}
        aria-busy={isLoading || undefined}
      >
        {content}
      </Link>
    );
  }

  if (href) {
    return (
      <span
        className={classes}
        aria-disabled="true"
        aria-busy={isLoading || undefined}
      >
        {content}
      </span>
    );
  }

  return (
    <button
      {...rest}
      type={type}
      disabled={isDisabled}
      aria-busy={isLoading || undefined}
      className={classes}
    >
      {content}
    </button>
  );
}

