+    expect(screen.getByTestId("activities-skeleton")).toBeInTheDocument();
+    expect(container.querySelector("[data-status]")).toHaveAttribute(
+      "data-status",
+      "loading",
+    );
+    expect(
+      container.querySelector("[data-status]"),
