// Login, Logout, Forgot Password, Reset Password, Change Password, Get current user
import { api } from "@/libs/api-client";
import type {
  AuthResponse, ChangePasswordRequest, ForgotPasswordRequest,
  LoginRequest, MessageResponse, ResetPasswordRequest,
} from "@/features/auth/types/auth.dto";

import type { SessionUser } from "@/features/auth/types";

const BASE = "/auth";

class AuthService {
  async login(data: LoginRequest): Promise<AuthResponse> {
    return api.post<AuthResponse>(`${BASE}/login`, data);
  }

  async logout(): Promise<void> {
    return api.post<void>(`${BASE}/logout`);
  }

  async getMe(): Promise<SessionUser> {
    return api.get<SessionUser>(`${BASE}/me`);
  }

  async forgotPassword(data: ForgotPasswordRequest): Promise<MessageResponse> {
    return api.post<MessageResponse>(`${BASE}/forgot-password`, data);
  }

  async resetPassword(data: ResetPasswordRequest): Promise<MessageResponse> {
    return api.post<MessageResponse>(`${BASE}/reset-password`, data);
  }

  async changePassword(data: ChangePasswordRequest): Promise<MessageResponse> {
    return api.post<MessageResponse>(`${BASE}/change-password`, data);
  }
}

export const authService = new AuthService();

import { RoleCode } from "@/libs/roles";
import type { ID, PermissionCode } from "@/types/entities";



export type Session = {
  userId: string;
  role: RoleCode
};


interface SessionUserBase {
  userId: ID;
  email: string;
  fullName: string;
  avatarUrl: string | null;
  permissions: PermissionCode[];
}

export interface StudentSessionUser extends SessionUserBase {
  role: "student";
  studentNumber: string;
  facultyId: ID;
}

export interface StaffSessionUser extends SessionUserBase {
  role: Exclude<RoleCode, "student">;
  studentNumber: string | null;
  facultyId: ID | null;
}

export type SessionUser = StudentSessionUser | StaffSessionUser;

export type UserWithStudentProfile = SessionUser & {
  studentNumber: string;
  facultyId: ID;
};

export function hasStudentProfile(user: SessionUser): user is UserWithStudentProfile {
  return user.studentNumber !== null && user.facultyId !== null;
}
"use client";

import { AuthContext } from "@/features/auth/context/AuthContext";
import { mockAuthService } from "@/features/auth/services/mock.auth.service";
import { SessionUser } from "@/features/auth/types/auth";
import { LoginRequest } from "@/features/auth/types/auth.dto";
import { useState, useCallback, useEffect, useMemo } from "react";

interface AuthProviderProps {
  children: React.ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<SessionUser | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  const authServiceInstance = mockAuthService;
  const removeUser = useCallback(async () => {
    setUser(null);
  }, []);

  const login = useCallback(
    async (data: LoginRequest) => {
      try {
        setIsLoading(true);
        const response = await authServiceInstance.login(data);
        if (response.user != null) {
          setUser(response.user);
          return response.user;
        }
        throw new Error("Login failed: user is null");
      } catch (error) {
        await removeUser();
        console.error("Login failed", error);
        throw error;
      } finally {
        setIsLoading(false);
      }
    },
    [authServiceInstance, removeUser],
  );

  const logout = useCallback(async () => {
    try {
      setIsLoading(true);
      await authServiceInstance.logout();
      await removeUser();
    } catch (error) {
      console.error("Logout failed", error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [authServiceInstance, removeUser]);

  const refreshUser = useCallback(async () => {
    try {
      setIsLoading(true);
      const response = await authServiceInstance.getMe();
      if (response) {
        setUser(response);
      }
    } catch (error) {
      await removeUser();
      console.error("Refresh user failed", error);
      throw error;
    } finally {
      setIsLoading(false);
    }
  }, [authServiceInstance, removeUser]);

  useEffect(() => {
    const initializeUser = async () => {
      try {
        await refreshUser();
      } catch (error) {
        console.error("Failed to initialize user", error);
      }
    };

    void initializeUser();
  }, [refreshUser]);

  const value = useMemo(
    () => ({
      user,
      isAuthenticated: user !== null,
      login,
      logout,
      refreshUser,
      isLoading,
    }),
    [user, login, logout, refreshUser, isLoading],
  );

  return (
    <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
  );
}
import { cn } from "@/libs/cn";

type SkeletonProps = {
  className?: string;
};

export function Skeleton({ className }: SkeletonProps) {
  return (
    <div
      aria-hidden="true"
      className={cn(
        "animate-pulse rounded-lg bg-slate-200 motion-reduce:animate-none",
        className,
      )}
    />
  );
}
import type { ReactNode } from "react";
import { cn } from "@/libs/cn";

