const LANDING_TIME_ZONE = "Asia/Ho_Chi_Minh";

type DateParts = {
  day: string;
  month: string;
  year: string;
  hour: string;
  minute: string;
};

function getParts(value: Date): DateParts | null {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) {
    return null;
  }

  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: LANDING_TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  }).formatToParts(value);

  const get = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((part) => part.type === type)?.value ?? "";

  return {
    day: get("day"),
    month: get("month"),
    year: get("year"),
    hour: get("hour"),
    minute: get("minute"),
  };
}

function toDate(parts: DateParts): string {
  return `${parts.day}/${parts.month}/${parts.year}`;
}

function toTime(parts: DateParts): string {
  return `${Number(parts.hour)}:${parts.minute}`;
}

export function formatActivityTime(start: Date, end: Date): string {
  const startParts = getParts(start);
  const endParts = getParts(end);

  if (!startParts || !endParts) {
    return "Invalid date";
  }

  const sameDay =
    startParts.day === endParts.day &&
    startParts.month === endParts.month &&
    startParts.year === endParts.year;

  if (sameDay) {
    return `${toDate(startParts)}, ${toTime(startParts)} - ${toTime(endParts)}`;
  }

  return `${toDate(startParts)} ${toTime(startParts)} - ${toDate(endParts)} ${toTime(endParts)}`;
}
import { describe, expect, it } from "vitest";
import { formatActivityTime } from "./format";

describe("formatActivityTime", () => {
  it("formats a same-day activity", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T08:00:00+07:00"),
        new Date("2026-10-17T10:00:00+07:00"),
      ),
    ).toBe("17/10/2026, 8:00 - 10:00");
  });

  it("formats a multi-day activity with both dates", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T08:00:00+07:00"),
        new Date("2026-10-18T10:00:00+07:00"),
      ),
    ).toBe("17/10/2026 8:00 - 18/10/2026 10:00");
  });

  it("formats midnight without a leading hour zero", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T00:05:00+07:00"),
        new Date("2026-10-17T00:30:00+07:00"),
      ),
    ).toBe("17/10/2026, 0:05 - 0:30");
  });

  it("keeps two-digit minutes", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-17T09:05:00+07:00"),
        new Date("2026-10-17T09:07:00+07:00"),
      ),
    ).toBe("17/10/2026, 9:05 - 9:07");
  });

  it("uses the Asia/Ho_Chi_Minh timezone at the UTC boundary", () => {
    expect(
      formatActivityTime(
        new Date("2026-10-16T17:00:00Z"),
        new Date("2026-10-16T19:00:00Z"),
      ),
    ).toBe("17/10/2026, 0:00 - 2:00");
  });

  it("renders a safe fallback for invalid dates", () => {
    expect(formatActivityTime(new Date("invalid"), new Date())).toBe(
      "Invalid date",
    );
  });
});
