  });
});

import { describe, expect, it } from "vitest";
import { fireEvent, screen, within } from "@testing-library/react";
import { ActivityCard } from "@/features/activities/components/ActivityCard";
import { createActivity } from "../../../../tests/fixtures";
import { renderWithProviders } from "../../../../tests/test-utils";

const placeholder = "/images/landing/activity-placeholder.png";

describe("ActivityCard", () => {
  it("uses one whole-card link with no nested link", () => {
    renderWithProviders(
      <ActivityCard activity={createActivity()} variant="featured" />,
    );

    const link = screen.getByRole("link");

    expect(screen.getAllByRole("link")).toHaveLength(1);
    expect(within(link).queryByRole("link")).not.toBeInTheDocument();
    expect(within(link).getByText("View")).toBeInTheDocument();
    expect(link).toHaveAttribute("href", "/activities/act-001");
  });

  it("clamps featured titles to four lines and compact titles to three", () => {
    const activity = createActivity();

    const { rerender } = renderWithProviders(
      <ActivityCard activity={activity} variant="featured" />,
    );

    expect(
      screen.getByRole("heading", { name: activity.title }),
    ).toHaveClass("line-clamp-4");

    rerender(<ActivityCard activity={activity} variant="compact" />);

    expect(
      screen.getByRole("heading", { name: activity.title }),
    ).toHaveClass("line-clamp-3");
  });

  it("omits unavailable categories and location", () => {
    const activity = createActivity({ categories: [], location: null });

    renderWithProviders(
      <ActivityCard activity={activity} variant="featured" />,
    );

    expect(screen.queryByText("Academic")).not.toBeInTheDocument();
    expect(screen.queryByText("I.32, HCMUS")).not.toBeInTheDocument();
    expect(screen.getByText("17/10/2026, 8:00 - 10:00")).toBeInTheDocument();
  });

  it("renders only the first compact category", () => {
    renderWithProviders(
      <ActivityCard
        activity={createActivity({ categories: ["Academic", "Science"] })}
        variant="compact"
      />,
    );

    expect(screen.getByText("Academic")).toBeInTheDocument();
    expect(screen.queryByText("Academic, Science")).not.toBeInTheDocument();
  });

  it("falls back to the local placeholder when no image exists", () => {
    renderWithProviders(
      <ActivityCard
        activity={createActivity({ imageUrl: null })}
        variant="featured"
      />,
    );

    expect(
      screen.getByRole("img", { name: "Sample Activity cover image" }),
    ).toHaveAttribute("src", placeholder);
  });

  it("falls back after an image load error", () => {
    renderWithProviders(
      <ActivityCard
        activity={createActivity({ imageUrl: "/broken-image.png" })}
        variant="featured"
      />,
    );

    const image = screen.getByRole("img", {
      name: "Sample Activity cover image",
    });
    expect(image).toHaveAttribute("src", "/broken-image.png");

    fireEvent.error(image);

    expect(image).toHaveAttribute("src", placeholder);
  });

  it("shows status text with a non-color cue only on featured cards", () => {
    const activity = createActivity({ registrationStatus: "upcoming" });
    const { rerender } = renderWithProviders(
      <ActivityCard activity={activity} variant="featured" />,
    );

    const status = screen.getByText("Registration Upcoming");
    const badge = status.parentElement;

    expect(badge?.querySelector('[aria-hidden="true"]')).not.toBeNull();

    rerender(<ActivityCard activity={activity} variant="compact" />);

    expect(screen.queryByText("Registration Upcoming")).not.toBeInTheDocument();
  });

  it("renders multi-day dates with both dates", () => {
    renderWithProviders(
      <ActivityCard
        activity={createActivity({
          startTime: new Date("2026-10-17T08:00:00+07:00"),
          endTime: new Date("2026-10-18T10:00:00+07:00"),
        })}
        variant="featured"
      />,
    );

    expect(
      screen.getByText("17/10/2026 8:00 - 18/10/2026 10:00"),
    ).toBeInTheDocument();
  });
});

import { describe, expect, it } from "vitest";
import { screen } from "@testing-library/react";
import { ActivityGrid } from "@/features/activities/components/ActivityGrid";
import { createActivity } from "../../../../tests/fixtures";
import { renderWithProviders } from "../../../../tests/test-utils";

function activity(id: string, title: string) {
  return createActivity({ id, title, href: `/activities/${id}` });
}

describe("ActivityGrid", () => {
  it("renders two featured cards and three compact cards", () => {
    renderWithProviders(
      <ActivityGrid
        activities={{
          featured: [
            activity("f-1", "Featured One"),
            activity("f-2", "Featured Two"),
          ],
          upcoming: [
            activity("u-1", "Upcoming One"),
            activity("u-2", "Upcoming Two"),
            activity("u-3", "Upcoming Three"),
          ],
        }}
      />,
    );

    const grid = screen.getByTestId("activity-grid");

    expect(grid).toHaveAttribute("data-layout", "grouped");
    expect(grid).toHaveClass("lg:grid-cols-[2fr_1fr]");
    expect(screen.getAllByRole("link")).toHaveLength(5);
    expect(
      screen.getByRole("heading", { name: "Featured One" }),
    ).toHaveClass("line-clamp-4");
    expect(
      screen.getByRole("heading", { name: "Upcoming One" }),
    ).toHaveClass("line-clamp-3");
  });

  it("renders one featured card with compact cards", () => {
    renderWithProviders(
      <ActivityGrid
        activities={{
          featured: [activity("f-1", "Only Featured")],
          upcoming: [activity("u-1", "Compact One")],
        }}
      />,
    );

    expect(screen.getByTestId("activity-grid")).toHaveAttribute(
      "data-layout",
      "grouped",
    );
    expect(screen.getAllByRole("link")).toHaveLength(2);
  });

  it("lets a single featured card span the grid width", () => {
    renderWithProviders(
      <ActivityGrid
        activities={{
          featured: [activity("f-1", "Only Featured")],
          upcoming: [],
        }}
      />,
    );

    const grid = screen.getByTestId("activity-grid");

    expect(grid).toHaveAttribute("data-layout", "featured-only");
    expect(grid).toHaveClass("grid", "gap-5");
    expect(grid).not.toHaveClass("sm:grid-cols-2");
    expect(screen.getAllByRole("link")).toHaveLength(1);
  });

  it("places two featured cards side by side", () => {
    renderWithProviders(
      <ActivityGrid
        activities={{
          featured: [
            activity("f-1", "Featured One"),
            activity("f-2", "Featured Two"),
          ],
          upcoming: [],
        }}
      />,
    );

    const grid = screen.getByTestId("activity-grid");

    expect(grid).toHaveAttribute("data-layout", "featured-only");
    expect(grid).toHaveClass("sm:grid-cols-2");
    expect(screen.getAllByRole("link")).toHaveLength(2);
  });

  it("renders up to five upcoming activities in a max-three-column grid", () => {
    renderWithProviders(
      <ActivityGrid
        activities={{
          featured: [],
          upcoming: Array.from({ length: 5 }, (_, index) =>
            activity(`u-${index + 1}`, `Upcoming ${index + 1}`),
          ),
        }}
      />,
    );

    const grid = screen.getByTestId("activity-grid");

    expect(grid).toHaveAttribute("data-layout", "upcoming-only");
    expect(grid).toHaveClass("lg:grid-cols-3");
    expect(screen.getAllByRole("link")).toHaveLength(5);
    expect(
      screen
        .getAllByRole("heading", { level: 3 })
        .every((heading) => heading.classList.contains("line-clamp-4")),
    ).toBe(true);
  });

  it("never renders a grid for an empty collection", () => {
    const { container } = renderWithProviders(
      <ActivityGrid activities={{ featured: [], upcoming: [] }} />,
    );

    expect(screen.queryByTestId("activity-grid")).not.toBeInTheDocument();
    expect(container).toBeEmptyDOMElement();
  });
});

import { describe, expect, it } from "vitest";
import { screen } from "@testing-library/react";
import { ServiceCard } from "@/features/landing/components/ServiceCard";
import { SERVICES } from "@/features/landing/config/services";
import { renderWithProviders } from "../../../../tests/test-utils";

const publicService = SERVICES[0];
const privateService = SERVICES[1];

describe("ServiceCard", () => {
  it("renders locked cards without a link, destination, or selection", () => {
    const { container } = renderWithProviders(
      <ServiceCard service={privateService} locked />,
    );

    const card = container.firstElementChild;

    expect(screen.queryByRole("link")).not.toBeInTheDocument();
    expect(container.querySelector("a")).toBeNull();
    expect(container.innerHTML).not.toContain(privateService.href);
    expect(card).toHaveAttribute("aria-hidden", "true");
    expect(card).toHaveAttribute("inert");
    expect(card).toHaveClass("select-none", "blur-[3px]");
    expect(screen.getByText("Tuition Payment")).toBeInTheDocument();
    expect(screen.getByText("Access")).toBeInTheDocument();
  });

  it("renders an unlocked public service as an external whole-card link", () => {
    renderWithProviders(
      <ServiceCard service={publicService} locked={false} />,
    );

    const link = screen.getByRole("link", {
      name: "Moodle (opens in a new tab)",
    });

    expect(link).toHaveAttribute("href", publicService.href);
    expect(link).toHaveAttribute("target", "_blank");
    expect(link).toHaveAttribute("rel", "noopener noreferrer");
    expect(link).toHaveTextContent("Moodle");
    expect(link).toHaveTextContent("Access");
  });

  it("renders an unavailable card without a dead link", () => {
    const { container } = renderWithProviders(
      <ServiceCard
        service={{ ...publicService, available: false }}
        locked={false}
      />,
    );

    expect(screen.getByText("Coming soon")).toBeInTheDocument();
    expect(screen.queryByRole("link")).not.toBeInTheDocument();
    expect(container.querySelector("a")).toBeNull();
    expect(container.innerHTML).not.toContain(publicService.href);
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import { screen } from "@testing-library/react";
import { ServicesSection } from "@/features/landing/components/ServicesSection";
import { SERVICES } from "@/features/landing/config/services";
import { createAuthContextValue } from "../../../../tests/fixtures";
import { renderWithProviders } from "../../../../tests/test-utils";

const authMocks = vi.hoisted(() => ({
  useAuth: vi.fn(),
}));

vi.mock("@/hooks/useAuth", () => ({
  useAuth: authMocks.useAuth,
}));

function cardCount(container: HTMLElement) {
  return container.querySelector("#services .grid")?.children.length ?? 0;
}

beforeEach(() => {
  authMocks.useAuth.mockReturnValue(createAuthContextValue());
});

describe("ServicesSection", () => {
  it("locks authenticated services for guests while keeping public links usable", () => {
    const { container } = renderWithProviders(<ServicesSection />);

    expect(screen.getByRole("heading", {
      name: "Quick access to essential university services",
    })).toBeInTheDocument();
    expect(cardCount(container)).toBe(SERVICES.length);
    expect(screen.getAllByRole("link")).toHaveLength(2);
    expect(
      screen.getByRole("link", { name: "Moodle (opens in a new tab)" }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("link", { name: "Student Portal (opens in a new tab)" }),
    ).toBeInTheDocument();
    expect(
      screen.queryByRole("link", { name: /Tuition Payment/ }),
    ).not.toBeInTheDocument();
    expect(
      screen.queryByRole("link", { name: /HCMUS Website/ }),
    ).not.toBeInTheDocument();

    const lockedCard = screen
      .getByText("Tuition Payment")
      .closest('[aria-hidden="true"]');

    expect(lockedCard).not.toBeNull();
    expect(lockedCard).toHaveAttribute("inert");
    expect(screen.queryByText(/sign in/i)).not.toBeInTheDocument();
  });

  it("treats the loading state as locked but stable", () => {
    authMocks.useAuth.mockReturnValue(
      createAuthContextValue({ isLoading: true }),
    );

    const { container } = renderWithProviders(<ServicesSection />);

    expect(cardCount(container)).toBe(SERVICES.length);
    expect(screen.getAllByRole("link")).toHaveLength(2);
    expect(
      screen.getByText("Tuition Payment").closest('[aria-hidden="true"]'),
    ).not.toBeNull();
  });

  it("unlocks all configured services for authenticated users", () => {
    authMocks.useAuth.mockReturnValue(
      createAuthContextValue({
        user: {
          userId: "student-1",
          email: "student@hcmus.edu.vn",
          fullName: "Student",
          avatarUrl: null,
          permissions: [],
          role: "student",
          studentNumber: "22120001",
          facultyId: "faculty-1",
        },
        isAuthenticated: true,
        isLoading: false,
      }),
    );

    const { container } = renderWithProviders(<ServicesSection />);

    expect(cardCount(container)).toBe(SERVICES.length);
    expect(screen.getAllByRole("link")).toHaveLength(SERVICES.length);
    expect(container.querySelector("[inert]")).toBeNull();

    for (const service of SERVICES) {
      expect(
        screen.getByRole("link", {
          name: `${service.name} (opens in a new tab)`,
        }),
      ).toHaveAttribute("href", service.href);
    }
  });

  it("keeps the same number of cards between guest and authenticated states", () => {
    authMocks.useAuth.mockReturnValue(createAuthContextValue());

    const { container, rerender } = renderWithProviders(<ServicesSection />);
    const guestCount = cardCount(container);

    authMocks.useAuth.mockReturnValue(
      createAuthContextValue({
        user: {
          userId: "admin-1",
          email: "admin@hcmus.edu.vn",
          fullName: "Admin",
          avatarUrl: null,
          permissions: [],
          role: "admin",
          studentNumber: null,
          facultyId: null,
        },
        isAuthenticated: true,
        isLoading: false,
      }),
    );

    rerender(<ServicesSection />);

    expect(cardCount(container)).toBe(guestCount);
    expect(screen.getAllByRole("link")).toHaveLength(SERVICES.length);
  });
});

