const fs = require("node:fs");

const BASE = "http://127.0.0.1:9223";
const OUT = "C:\\Users\\HP\\AppData\\Local\\Temp\\opencode\\landing-shots";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) {
        reject(new Error(JSON.stringify(message.error)));
      } else {
        resolve(message.result);
      }
    }
  };

  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await send("Page.enable");
  await send("Runtime.enable");

  const widths = [320, 375, 640, 768, 1024, 1440, 1920];

  for (const width of widths) {
    await send("Emulation.setDeviceMetricsOverride", {
      width,
      height: 10000,
      deviceScaleFactor: 1,
      mobile: width < 768,
      screenWidth: width,
      screenHeight: 10000,
    });
    await send("Page.navigate", { url: "http://localhost:3210/" });
    await sleep(6000);

    const measured = await send("Runtime.evaluate", {
      expression: `(() => {
        const elements = [...document.querySelectorAll("header, main, footer")];
        const bottom = Math.max(
          ...elements.map((element) => element.getBoundingClientRect().bottom + window.scrollY),
        );
        return {
          contentHeight: Math.ceil(bottom),
          innerWidth: window.innerWidth,
          scrollWidth: document.documentElement.scrollWidth,
          bodyScrollWidth: document.body.scrollWidth,
        };
      })()`,
      returnByValue: true,
    });

    const { contentHeight, innerWidth, scrollWidth, bodyScrollWidth } =
      measured.result.value;
    const height = Math.max(1, contentHeight);

    const screenshot = await send("Page.captureScreenshot", {
      format: "png",
      captureBeyondViewport: true,
      clip: { x: 0, y: 0, width, height, scale: 1 },
    });

    fs.writeFileSync(
      `${OUT}\\cdp-${width}.png`,
      Buffer.from(screenshot.data, "base64"),
    );

    console.log(
      JSON.stringify({
        width,
        innerWidth,
        scrollWidth,
        bodyScrollWidth,
        overflow: scrollWidth > innerWidth || bodyScrollWidth > innerWidth,
        contentHeight: height,
      }),
    );
  }

  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

