const fs = require("node:fs");

const BASE = "http://127.0.0.1:9223";
const AXE = fs.readFileSync(
  "E:\\HCMUS\\Third Year\\HK1\\CS300 - SE\\project\\project\\cs300-project\\src\\client\\node_modules\\axe-core\\axe.min.js",
  "utf8",
);

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) {
        reject(new Error(JSON.stringify(message.error)));
      } else {
        resolve(message.result);
      }
    }
  };

  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  await send("Page.enable");
  await send("Runtime.enable");

  for (const width of [375, 1440]) {
    await send("Emulation.setDeviceMetricsOverride", {
      width,
      height: 10000,
      deviceScaleFactor: 1,
      mobile: width < 768,
      screenWidth: width,
      screenHeight: 10000,
    });
    await send("Page.navigate", { url: "http://localhost:3210/" });
    await sleep(6000);

    await send("Runtime.evaluate", {
      expression: `${AXE}; true`,
      returnByValue: true,
    });

    const result = await send("Runtime.evaluate", {
      expression: `axe.run(document, { resultTypes: ["violations", "incomplete"] }).then((results) => ({
        violations: results.violations.map((violation) => ({
          id: violation.id,
          impact: violation.impact,
          help: violation.help,
          nodes: violation.nodes.map((node) => ({
            target: node.target,
            summary: node.failureSummary,
          })),
        })),
        incomplete: results.incomplete.map((item) => ({
          id: item.id,
          impact: item.impact,
          nodes: item.nodes.map((node) => node.target),
        })),
      }))`,
      awaitPromise: true,
      returnByValue: true,
    });

    const value = result.result.value;

    console.log(`\n=== width ${width} ===`);
    console.log(
      JSON.stringify(
        {
          violations: value.violations,
          incompleteIds: value.incomplete.map((item) => item.id),
        },
        null,
        2,
      ),
    );
  }

  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

