const BASE = "http://127.0.0.1:9223";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) {
        reject(new Error(JSON.stringify(message.error)));
      } else {
        resolve(message.result);
      }
    }
  };

  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  }

  async function pressTab() {
    await send("Input.dispatchKeyEvent", {
      type: "keyDown",
      key: "Tab",
      code: "Tab",
      windowsVirtualKeyCode: 9,
    });
    await send("Input.dispatchKeyEvent", {
      type: "keyUp",
      key: "Tab",
      code: "Tab",
      windowsVirtualKeyCode: 9,
    });
    await sleep(100);
  }

  async function pressEscape() {
    await send("Input.dispatchKeyEvent", {
      type: "keyDown",
      key: "Escape",
      code: "Escape",
      windowsVirtualKeyCode: 27,
    });
    await send("Input.dispatchKeyEvent", {
      type: "keyUp",
      key: "Escape",
      code: "Escape",
      windowsVirtualKeyCode: 27,
    });
    await sleep(300);
  }

  function activeElementExpression() {
    return `(() => {
      const element = document.activeElement;
      if (!element || element === document.body) return "BODY";
      return {
        tag: element.tagName,
        text: (element.textContent || "").trim().slice(0, 40),
        ariaLabel: element.getAttribute("aria-label"),
        href: element.getAttribute("href"),
        inDialog: Boolean(element.closest("dialog")),
      };
    })()`;
  }

  await send("Page.enable");
  await send("Runtime.enable");

  await send("Emulation.setDeviceMetricsOverride", {
    width: 1440,
    height: 900,
    deviceScaleFactor: 1,
    mobile: false,
    screenWidth: 1440,
    screenHeight: 900,
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });
  await sleep(5000);
  await evaluate("document.activeElement && document.activeElement.blur(); true");

  const desktopOrder = [];
  for (let index = 0; index < 12; index++) {
    await pressTab();
    desktopOrder.push(await evaluate(activeElementExpression()));
  }

  console.log("DESKTOP_TAB_ORDER");
  console.log(JSON.stringify(desktopOrder, null, 2));

  await send("Emulation.setDeviceMetricsOverride", {
    width: 375,
    height: 800,
    deviceScaleFactor: 1,
    mobile: true,
    screenWidth: 375,
    screenHeight: 800,
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });
  await sleep(5000);

  const opened = await evaluate(`(() => {
    const trigger = document.querySelector('[aria-label="Open navigation menu"]');
    if (!trigger) return false;
    trigger.click();
    return true;
  })()`);
  await sleep(500);

  const drawerState = await evaluate(`(() => {
    const dialog = document.querySelector("#mobile-navigation");
    return {
      exists: Boolean(dialog),
      open: Boolean(dialog && dialog.open),
      active: document.activeElement && document.activeElement.getAttribute("aria-label"),
    };
  })()`);

  const drawerOrder = [];
  for (let index = 0; index < 8; index++) {
    drawerOrder.push(await evaluate(activeElementExpression()));
    await pressTab();
  }
  drawerOrder.push(await evaluate(activeElementExpression()));

  await pressEscape();

  const closedState = await evaluate(`(() => {
    const dialog = document.querySelector("#mobile-navigation");
    return {
      open: Boolean(dialog && dialog.open),
      active: document.activeElement && document.activeElement.getAttribute("aria-label"),
    };
  })()`);

  console.log("MOBILE_DRAWER");
  console.log(JSON.stringify({ opened, drawerState, drawerOrder, closedState }, null, 2));

  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

