const BASE = "http://127.0.0.1:9223";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) {
        reject(new Error(JSON.stringify(message.error)));
      } else {
        resolve(message.result);
      }
    }
  };

  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", {
    width: 1440,
    height: 900,
    deviceScaleFactor: 1,
    mobile: false,
    screenWidth: 1440,
    screenHeight: 900,
  });

  const results = {};

  for (const motion of ["no-preference", "reduce"]) {
    await send("Emulation.setEmulatedMedia", {
      features: [{ name: "prefers-reduced-motion", value: motion }],
    });
    await send("Page.navigate", { url: "http://localhost:3210/" });
    await sleep(5000);

    const card = await evaluate(`(() => {
      const link = document.querySelector('a[href^="/activities/"]');
      if (!link) return null;
      const rect = link.getBoundingClientRect();
      return { x: Math.round(rect.x + rect.width / 2), y: Math.round(rect.y + rect.height / 2) };
    })()`);

    if (card) {
      await send("Input.dispatchMouseEvent", {
        type: "mouseMoved",
        x: card.x,
        y: card.y,
      });
      await sleep(500);
    }

    results[motion] = await evaluate(`(() => {
      const link = document.querySelector('a[href^="/activities/"]');
      const styles = link ? getComputedStyle(link) : null;
      const skeleton = document.querySelector('[class*="animate-pulse"]');
      return {
        scrollBehavior: getComputedStyle(document.documentElement).scrollBehavior,
        transitionDuration: styles ? styles.transitionDuration : null,
        transform: styles ? styles.transform : null,
        skeletonAnimation: skeleton
          ? getComputedStyle(skeleton).animationName
          : "no-skeleton",
      };
    })()`);
  }

  console.log(JSON.stringify(results, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

