const BASE = "http://127.0.0.1:9223";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) {
        reject(new Error(JSON.stringify(message.error)));
      } else {
        resolve(message.result);
      }
    }
  };

  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", {
    width: 1440,
    height: 1000,
    deviceScaleFactor: 1,
    mobile: false,
    screenWidth: 1440,
    screenHeight: 1000,
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });
  await sleep(6000);

  const summary = await evaluate(`(() => {
    const links = [...document.querySelectorAll("a")];
    const header = document.querySelector("header");
    const hero = document.querySelector("#home");
    const activityLinks = [...document.querySelectorAll('a[href^="/activities/"]')];
    const services = document.querySelector("#services");
    const serviceLinks = services ? [...services.querySelectorAll("a")] : [];
    const lockedCards = services ? [...services.querySelectorAll('[aria-hidden="true"][inert]')] : [];
    const sectionIds = [...document.querySelectorAll("main > section[id], footer[id]")].map((element) => element.id);
    const loginLink = header ? header.querySelector('a[href^="/login"]') : null;
    const getStarted = hero ? hero.querySelector("a") : null;
    return {
      headerLogin: loginLink ? { text: loginLink.textContent.trim(), href: loginLink.getAttribute("href") } : null,
      headerDashboard: header ? Boolean(header.querySelector('a[href$="/dashboard"]')) : false,
      heroFirstAction: getStarted ? { text: getStarted.textContent.trim(), href: getStarted.getAttribute("href") } : null,
      sectionIds,
      activityCount: activityLinks.length,
      featuredCount: [...document.querySelectorAll("main a[href^='/activities/'] .aspect-video")].length,
      compactCount: [...document.querySelectorAll("main a[href^='/activities/'] .h-24.w-28")].length,
      serviceLinkCount: serviceLinks.length,
      serviceLinks: serviceLinks.map((link) => link.getAttribute("href")),
      lockedCardCount: lockedCards.length,
      lockedCardText: lockedCards.map((card) => card.textContent.trim().slice(0, 40)),
      lockedHrefsInDom: lockedCards.flatMap((card) => [...card.querySelectorAll("[href]")].map((node) => node.getAttribute("href"))),
      totalLinkCount: links.length,
    };
  })()`);

  console.log(JSON.stringify(summary, null, 2));

  console.log("TAB_ORDER");
  await evaluate("document.activeElement && document.activeElement.blur(); true");
  const order = [];
  for (let index = 0; index < 30; index++) {
    await send("Input.dispatchKeyEvent", {
      type: "keyDown",
      key: "Tab",
      code: "Tab",
      windowsVirtualKeyCode: 9,
    });
    await send("Input.dispatchKeyEvent", {
      type: "keyUp",
      key: "Tab",
      code: "Tab",
      windowsVirtualKeyCode: 9,
    });
    await sleep(60);
    const item = await evaluate(`(() => {
      const element = document.activeElement;
      if (!element || element === document.body) return "BODY";
      return {
        tag: element.tagName,
        text: (element.textContent || "").trim().slice(0, 32),
        href: element.getAttribute("href"),
        inServices: Boolean(element.closest("#services")),
      };
    })()`);
    order.push(item);
  }
  console.log(JSON.stringify(order, null, 2));

  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

