const BASE = "http://127.0.0.1:9223";
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  };
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", {
    width: 1440,
    height: 1000,
    deviceScaleFactor: 1,
    mobile: false,
    screenWidth: 1440,
    screenHeight: 1000,
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });
  await sleep(6000);

  const summary = await evaluate(`(() => {
    const header = document.querySelector("header");
    const hero = document.querySelector("#home");
    const authLink = header
      ? [...header.querySelectorAll("a")].find((link) => /Dashboard|Log In/.test(link.textContent))
      : null;
    const getStarted = hero ? hero.querySelector("a") : null;
    const services = document.querySelector("#services");
    const serviceLinks = services ? [...services.querySelectorAll("a")] : [];
    const locked = services ? [...services.querySelectorAll("[inert]")] : [];
    return {
      headerAuth: authLink
        ? { text: authLink.textContent.trim(), href: authLink.getAttribute("href") }
        : null,
      getStarted: getStarted
        ? { text: getStarted.textContent.trim(), href: getStarted.getAttribute("href") }
        : null,
      serviceLinkCount: serviceLinks.length,
      lockedCount: locked.length,
    };
  })()`);

  console.log(JSON.stringify(summary, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

