const BASE = "http://127.0.0.1:9223";
const scenario = process.argv[2] || "success";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, {
    method: "PUT",
  }).then((response) => response.json());
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  };
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    return result.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", {
    width: 1440,
    height: 1000,
    deviceScaleFactor: 1,
    mobile: false,
    screenWidth: 1440,
    screenHeight: 1000,
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });
  await sleep(800);

  const early = await evaluate(`(() => {
    const state = document.querySelector("#activities [data-status]");
    return {
      status: state ? state.getAttribute("data-status") : null,
      skeleton: Boolean(document.querySelector('[data-testid="activities-skeleton"]')),
      header: Boolean(document.querySelector("header")),
      hero: Boolean(document.querySelector("#home h1")),
      footer: Boolean(document.querySelector("footer")),
    };
  })()`);

  await sleep(3200);

  const final = await evaluate(`(() => {
    const section = document.querySelector("#activities");
    const grid = document.querySelector('[data-testid="activity-grid"]');
    const featuredImages = section
      ? [...section.querySelectorAll('a[href^="/activities/"] .aspect-video')]
      : [];
    const compactImages = section
      ? [...section.querySelectorAll('a[href^="/activities/"] .h-24.w-28')]
      : [];
    const titles = section
      ? [...section.querySelectorAll('a[href^="/activities/"] h3')]
      : [];
    const firstImage = featuredImages[0]
      ? featuredImages[0].querySelector("img")
      : null;
    return {
      status: section
        ? section.querySelector("[data-status]")?.getAttribute("data-status")
        : null,
      layout: grid ? grid.getAttribute("data-layout") : null,
      featuredCount: featuredImages.length,
      compactCount: compactImages.length,
      totalCards: section
        ? section.querySelectorAll('a[href^="/activities/"]').length
        : 0,
      emptyText: section
        ? section.textContent.includes("No activities available right now")
        : false,
      errorText: section
        ? section.textContent.includes("We couldn't load activities")
        : false,
      retryButton: Boolean(
        section && [...section.querySelectorAll("button")].find((button) => /Try again/.test(button.textContent)),
      ),
      skeleton: Boolean(document.querySelector('[data-testid="activities-skeleton"]')),
      overflow:
        document.documentElement.scrollWidth > window.innerWidth ||
        document.body.scrollWidth > window.innerWidth,
      header: Boolean(document.querySelector("header")),
      hero: Boolean(document.querySelector("#home h1")),
      footer: Boolean(document.querySelector("footer")),
      firstTitle: titles[0] ? titles[0].textContent.trim().slice(0, 60) : null,
      firstTitleClamp: titles[0]
        ? getComputedStyle(titles[0]).webkitLineClamp
        : null,
      firstImageSrc: firstImage ? firstImage.currentSrc || firstImage.getAttribute("src") : null,
      dateText: section
        ? (section.textContent.match(/\\d{2}\\/\\d{2}\\/\\d{4}[^A-Z]*/g) || []).slice(0, 2)
        : [],
    };
  })()`);

  let retry = null;
  if (scenario === "error") {
    retry = [];
    for (let attempt = 0; attempt < 3; attempt++) {
      const before = await evaluate(`(() => {
        const section = document.querySelector("#activities");
        return {
          status: section.querySelector("[data-status]")?.getAttribute("data-status"),
          errorNodes: section.textContent.split("We couldn't load activities").length - 1,
        };
      })()`);
      await evaluate(`(() => {
        const button = [...document.querySelectorAll("#activities button")].find((node) => /Try again/.test(node.textContent));
        if (button) button.click();
        return true;
      })()`);
      await sleep(800);
      const after = await evaluate(`(() => {
        const section = document.querySelector("#activities");
        return {
          status: section.querySelector("[data-status]")?.getAttribute("data-status"),
          errorNodes: section.textContent.split("We couldn't load activities").length - 1,
          activeText: document.activeElement ? document.activeElement.textContent.trim().slice(0, 40) : null,
        };
      })()`);
      retry.push({ before, after });
    }
  }

  console.log(JSON.stringify({ scenario, early, final, retry }, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

