import { CloseIcon } from "@/components/icons/CloseIcon";
import { MenuIcon } from "@/components/icons/MenuIcon";
import { Logo } from "@/components/layout/Logo";
import { Button } from "@/components/ui/Button";
import { Container } from "@/components/ui/Container";
import { useAuth } from "@/hooks/useAuth";
import { getDashboardPath, getLoginHref } from "@/libs/navigation";
import { scrollToSection, useHashScroll, useScrollSpy } from "@/libs/scroll";
import { cn } from "@/libs/cn";
import type { NavigationLink } from "@/types/navigation";

type SiteHeaderProps = {
  links: NavigationLink[];
};

const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function SiteHeader({ links }: SiteHeaderProps) {
  const { user, isAuthenticated, isLoading } = useAuth();
  const [menuOpen, setMenuOpen] = useState(false);
  const dialogRef = useRef<HTMLDialogElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const restoreFocusRef = useRef(true);
  const activeSection = useScrollSpy(links.map((link) => link.id));

  useHashScroll();

  const returnTo =
    activeSection && activeSection !== "home" ? `/#${activeSection}` : "/";
  const loginHref = getLoginHref(returnTo);
  const authHref =
    isAuthenticated && user
      ? getDashboardPath(user.role)
      : loginHref;

  useEffect(() => {
    const dialog = dialogRef.current;

    if (!dialog) {
      return;
    }

    if (menuOpen) {
      if (!dialog.open) {
        dialog.showModal();
      }
      document.body.style.overflow = "hidden";
      requestAnimationFrame(() => {
        dialog
          .querySelector<HTMLElement>("[data-dialog-close]")
          ?.focus();
      });
    } else if (dialog.open) {
      dialog.close();
    }
  }, [menuOpen]);

  useEffect(() => {
    return () => {
      document.body.style.overflow = "";
    };
  }, []);

  const closeMenu = (restoreFocus = true) => {
    restoreFocusRef.current = restoreFocus;
    setMenuOpen(false);
  };

  const handleDialogClose = () => {
    document.body.style.overflow = "";
    setMenuOpen(false);

    if (restoreFocusRef.current) {
      requestAnimationFrame(() => triggerRef.current?.focus());
    }

    restoreFocusRef.current = true;
  };

  const handleBackdropClick = (event: MouseEvent<HTMLDialogElement>) => {
    if (event.target === event.currentTarget) {
      closeMenu();
    }
  };

  const handleDialogKeyDown = (event: KeyboardEvent<HTMLDialogElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeMenu();
      return;
    }

    if (event.key !== "Tab") {
      return;
    }

    const dialog = dialogRef.current;

    if (!dialog) {
      return;
    }

    const focusable = Array.from(
      dialog.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
    );

    if (focusable.length === 0) {
      event.preventDefault();
      return;
    }

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const current = document.activeElement;

    if (event.shiftKey && (current === first || current === dialog)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && current === last) {
      event.preventDefault();
      first.focus();
    }
  };

