const BASE = "http://127.0.0.1:9223";
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, { method: "PUT" }).then((response) => response.json());
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  };
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    return result.result.value;
  }
  async function navigate() {
    await send("Page.navigate", { url: "http://localhost:3210/" });
  }
  async function viewport(width, height) {
    await send("Emulation.setDeviceMetricsOverride", {
      width,
      height,
      deviceScaleFactor: 1,
      mobile: width < 1024,
      screenWidth: width,
      screenHeight: height,
    });
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Network.enable");
  await viewport(1440, 1000);
  await navigate();
  await sleep(3000);

  const staticInfo = await evaluate(`(() => {
    const meta = (selector) => document.querySelector(selector)?.getAttribute("content") || null;
    return {
      title: document.title,
      description: meta('meta[name="description"]'),
      ogTitle: meta('meta[property="og:title"]'),
      ogDescription: meta('meta[property="og:description"]'),
      ogImage: meta('meta[property="og:image"]'),
      twitterTitle: meta('meta[name="twitter:title"]'),
      h1Count: document.querySelectorAll("h1").length,
      h2Count: document.querySelectorAll("h2").length,
      h3Count: document.querySelectorAll("h3").length,
      sections: [...document.querySelectorAll("main > section")].map((section) => section.id),
      copyright: document.querySelector("footer")?.textContent.match(/┬⌐[^|]*/)?.[0]?.trim() || null,
      overflow: document.documentElement.scrollWidth > window.innerWidth,
    };
  })()`);

  await evaluate("window.scrollTo(0, 2200);");
  await sleep(500);
  const brand = await evaluate(`(async () => {
    const logo = document.querySelector('header a[href="#home"]');
    logo.click();
    await new Promise((resolve) => setTimeout(resolve, 900));
    return {
      hash: location.hash,
      scrollY: Math.round(window.scrollY),
      headerVisible: Boolean(document.querySelector("header")),
    };
  })()`);

  await viewport(375, 800);
  await navigate();
  await sleep(3000);
  const drawer = await evaluate(`(async () => {
    const trigger = document.querySelector('button[aria-controls="mobile-navigation"]');
    trigger.click();
    await new Promise((resolve) => setTimeout(resolve, 400));
    const dialog = document.querySelector("#mobile-navigation");
    const before = {
      open: dialog.open,
      closeFocused: document.activeElement?.getAttribute("data-dialog-close") !== null,
    };
    const link = [...dialog.querySelectorAll('a[href="#about"]')][0];
    const rectBefore = document.querySelector("#about").getBoundingClientRect().top;
    link.click();
    await new Promise((resolve) => setTimeout(resolve, 1100));
    return {
      before,
      after: {
        open: dialog.open,
        hash: location.hash,
        focusedId: document.activeElement?.id || null,
        aboutTop: Math.round(document.querySelector("#about").getBoundingClientRect().top),
        rectBefore: Math.round(rectBefore),
        overflow: document.documentElement.scrollWidth > window.innerWidth,
      },
    };
  })()`);

  await send("Network.setBlockedURLs", { urls: ["*hero.png*"] });
  await viewport(1440, 1000);
  await navigate();
  await sleep(3000);
  const heroFailure = await evaluate(`(() => ({
    heroHeading: document.querySelector("#home h1")?.textContent || null,
    heroImage: Boolean(document.querySelector('#home img[alt="HCMUS campus building and courtyard"]')),
    fallbackGradient: Boolean(document.querySelector("#home > div > div.absolute.inset-0.bg-gradient-to-br")),
    status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
    header: Boolean(document.querySelector("header")),
    footer: Boolean(document.querySelector("footer")),
    overflow: document.documentElement.scrollWidth > window.innerWidth,
  }))()`);
  await send("Network.setBlockedURLs", { urls: [] });

  await send("Network.setBlockedURLs", { urls: ["*highlight-activities*"] });
  await navigate();
  await sleep(3000);
  const activityImageFailure = await evaluate(`(() => {
    const image = document.querySelector('#activities a[href^="/activities/"] .aspect-video img');
    return {
      status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
      firstImage: image ? image.currentSrc || image.getAttribute("src") : null,
      usesPlaceholder: image ? (image.currentSrc || image.getAttribute("src")).includes("activity-placeholder") : false,
      cardCount: document.querySelectorAll('#activities a[href^="/activities/"]').length,
    };
  })()`);
  await send("Network.setBlockedURLs", { urls: [] });

  await send("Network.emulateNetworkConditions", {
    offline: false,
    latency: 2500,
    downloadThroughput: 30 * 1024,
    uploadThroughput: 30 * 1024,
    connectionType: "cellular3g",
  });
  await navigate();
  await sleep(1200);
  const throttled = await evaluate(`(() => ({
    status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
    skeleton: Boolean(document.querySelector('[data-testid="activities-skeleton"]')),
    hero: Boolean(document.querySelector("#home h1")),
    header: Boolean(document.querySelector("header")),
    footer: Boolean(document.querySelector("footer")),
    overflow: document.documentElement.scrollWidth > window.innerWidth,
  }))()`);
  await send("Network.emulateNetworkConditions", {
    offline: false,
    latency: 0,
    downloadThroughput: -1,
    uploadThroughput: -1,
  });
  await sleep(3500);
  const throttledAfter = await evaluate(`(() => ({
    status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
    cards: document.querySelectorAll('#activities a[href^="/activities/"]').length,
  }))()`);

  console.log(JSON.stringify({ staticInfo, brand, drawer, heroFailure, activityImageFailure, throttled, throttledAfter }, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

