    });
  }
  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    return result.result.value;
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Network.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false, screenWidth: 1440, screenHeight: 1000 });
  await send("Network.emulateNetworkConditions", {
    offline: false,
    latency: 1000,
    downloadThroughput: 60 * 1024,
    uploadThroughput: 60 * 1024,
    connectionType: "cellular3g",
  });
  await send("Page.navigate", { url: "http://localhost:3210/" });

  const states = [];
  let last = "";
  for (let i = 0; i < 22; i++) {
    await sleep(300);
    let state;
    try {
      state = await evaluate(`(() => ({
        ready: document.readyState,
        status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
        skeleton: Boolean(document.querySelector('[data-testid="activities-skeleton"]')),
        hero: Boolean(document.querySelector("#home h1")),
        header: Boolean(document.querySelector("header")),
        footer: Boolean(document.querySelector("footer")),
        overflow: document.documentElement.scrollWidth > window.innerWidth,
      }))()`);
    } catch {
      state = { ready: "evaluate-error" };
    }
    const key = JSON.stringify(state);
    if (key !== last) {
      states.push({ ms: (i + 1) * 300, ...state });
      last = key;
    }
  }

  await send("Network.emulateNetworkConditions", {
    offline: false,
    latency: 0,
    downloadThroughput: -1,
    uploadThroughput: -1,
  });
  await sleep(3000);
  const final = await evaluate(`(() => ({
    status: document.querySelector("#activities [data-status]")?.getAttribute("data-status") || null,
    cards: document.querySelectorAll('#activities a[href^="/activities/"]').length,
    overflow: document.documentElement.scrollWidth > window.innerWidth,
  }))()`);

  console.log(JSON.stringify({ states, final }, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

