const fs = require("node:fs");
const BASE = "http://127.0.0.1:9223";
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const target = await fetch(`${BASE}/json/new?about:blank`, { method: "PUT" }).then((r) => r.json());
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });

  let nextId = 1;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      if (message.error) reject(new Error(JSON.stringify(message.error)));
      else resolve(message.result);
    }
  };
  function send(method, params = {}) {
    const id = nextId++;
    return new Promise((resolve, reject) => {
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async function evaluate(expression) {
    const result = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
    return result.result.value;
  }
  async function setViewport(width, height) {
    await send("Emulation.setDeviceMetricsOverride", {
      width,
      height,
      deviceScaleFactor: 1,
      mobile: width < 1024,
      screenWidth: width,
      screenHeight: height,
    });
  }
  async function audit(width, height) {
    await setViewport(width, height);
    await send("Page.navigate", { url: "http://localhost:3210/" });
    await sleep(2500);
    const info = await evaluate(`(() => {
      const section = document.querySelector("#services");
      const grid = section.querySelector(".grid");
      const overlay = section.querySelector('[data-testid="services-lock-overlay"]');
      const login = [...section.querySelectorAll("a")].find((link) => /Log in for more/.test(link.textContent));
      const cards = [...grid.children];
      const rows = new Set(cards.map((card) => Math.round(card.getBoundingClientRect().top)));
      const columns = new Set(cards.map((card) => Math.round(card.getBoundingClientRect().left)));
      const overlayStyle = getComputedStyle(overlay);
      return {
        cards: cards.length,
        rows: rows.size,
        columns: columns.size,
        cardLinks: grid.querySelectorAll("a").length,
        inertCards: cards.filter((card) => card.hasAttribute("inert") && card.getAttribute("aria-hidden") === "true").length,
        cardNames: [...section.querySelectorAll(".grid span.block")].map((node) => node.textContent),
        overlay: {
          backdropFilter: overlayStyle.backdropFilter,
          backgroundImage: overlayStyle.backgroundImage,
          pointerEvents: overlayStyle.pointerEvents,
          coversGrid: Math.round(overlay.getBoundingClientRect().height) === Math.round(grid.getBoundingClientRect().height),
        },
        login: login ? { text: login.textContent.trim(), href: login.getAttribute("href") } : null,
        overflow: document.documentElement.scrollWidth > window.innerWidth,
      };
    })()`);
    const rect = await evaluate(`(() => {
      const el = document.querySelector("#services");
      const r = el.getBoundingClientRect();
      return { x: r.left + window.scrollX, y: r.top + window.scrollY, width: r.width, height: r.height };
    })()`);
    const shot = await send("Page.captureScreenshot", {
      format: "png",
      captureBeyondViewport: true,
      clip: { ...rect, scale: 1 },
    });
    const file = `C:\\Users\\HP\\AppData\\Local\\Temp\\opencode\\landing-shots\\services-${width}.png`;
    fs.writeFileSync(file, Buffer.from(shot.data, "base64"));
    return { file, ...info };
  }

  await send("Page.enable");
  await send("Runtime.enable");
  const desktop = await audit(1440, 1000);
  const mobile = await audit(375, 800);
  console.log(JSON.stringify({ desktop, mobile }, null, 2));
  ws.close();
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

