import { SurfaceCard } from "@/components/ui/SurfaceCard";
import {
  HELP_CONTENT,
  type GuideEntry,
} from "@/features/landing/config/guides";
import { cn } from "@/libs/cn";

type GuideCardProps = {
  guide: GuideEntry;
};

export function GuideCard({ guide }: GuideCardProps) {
  const content = (
    <>
      <div className="min-w-0">
        <h3 className="text-base font-bold text-text">{guide.title}</h3>
        <p className="mt-1 text-sm text-text-muted">{guide.subtitle}</p>
        {!guide.available ? (
          <Badge tone="neutral" className="mt-2 text-[11px]">
            {HELP_CONTENT.unavailableLabel}
          </Badge>
        ) : null}
      </div>
      <ArrowRightIcon
        aria-hidden="true"
        className={cn(
          "size-5 shrink-0",
          guide.available ? "text-primary" : "text-text-muted/60",
        )}
      />
    </>
  );

  if (guide.available && guide.href) {
    return (
      <Link
        href={guide.href}
        className="group flex min-h-24 items-center justify-between gap-4 rounded-2xl border border-slate-200/80 bg-gradient-to-b from-guide-gradient-from to-guide-gradient-to px-6 py-5 shadow-sm transition hover:shadow-md focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring"
      >
        {content}
      </Link>
    );
  }

  return (
    <SurfaceCard
      gradient
      className="flex min-h-24 items-center justify-between gap-4 border border-slate-200/80 px-6 py-5"
    >
      {content}
    </SurfaceCard>
  );
}
export type GuideEntry = {
  id: string;
  title: string;
  subtitle: string;
  href: string | null;
  available: boolean;
};

export const HELP_CONTENT = {
  eyebrow: "Help / Guide",
  title: "Find quick guides and answers to common questions.",
  unavailableLabel: "Coming soon",
};

export const GUIDES: GuideEntry[] = [
  {
    id: "getting-started",
    title: "GETTING STARTED",
    subtitle: "Learn the basics",
    href: null,
    available: false,
  },
  {
    id: "activities",
    title: "ACTIVITIES",
    subtitle: "How to register?",
    href: null,
    available: false,
  },
  {
    id: "training-score",
    title: "TRAINING SCORE",
    subtitle: "Track your DRS",
    href: null,
    available: false,
  },
  {
    id: "faq",
    title: "FAQ",
    subtitle: "Common questions",
    href: null,
    available: false,
  },
];
import { Container } from "@/components/ui/Container";
import { CopyrightYear } from "@/components/layout/CopyrightYear";
import { Logo } from "@/components/layout/Logo";
import type { FooterContent } from "@/types/site";

type SiteFooterProps = {
  content: FooterContent;
};

export function SiteFooter({ content }: SiteFooterProps) {
  return (
    <footer
      id="contact"
      aria-labelledby="footer-heading"
      className="scroll-mt-[calc(var(--header-height)+2rem)] bg-primary-dark text-white"
    >
      <h2 id="footer-heading" className="sr-only">
        Contact myHCMUS
      </h2>
      <Container className="grid gap-10 py-14 md:grid-cols-[1.4fr_1fr_1fr]">
        <div>
          <Logo variant="light" />
          <p className="mt-4 max-w-xs text-sm leading-6 text-white/75">
            {content.brandDescription}
          </p>
        </div>

        <div>
          <h3 className="text-sm font-semibold uppercase tracking-[0.14em] text-white/75">
            {content.contactHeading}
          </h3>
          <address className="mt-4 space-y-3 text-sm not-italic leading-6 text-white/85">
            <p>{content.address}</p>
            <p className="space-y-1">
              {content.phones.map((phone) => (
                <a
                  key={phone}
                  href={`tel:${phone.replace(/[^\d+]/g, "")}`}
                  className="block underline-offset-4 hover:underline"
                >
                  {phone}
                </a>
              ))}
            </p>
            <a
              href={`mailto:${content.email}`}
              className="inline-block underline-offset-4 hover:underline"
            >
              {content.email}
            </a>
          </address>
