import { LocationIcon } from "@/components/icons/LocationIcon";
import { cn } from "@/libs/cn";

type ActivityMetaProps = {
  dateTime: string;
  location: string | null;
  categories?: string[];
  compact?: boolean;
};

export function ActivityMeta({
  dateTime,
  location,
  categories = [],
  compact = false,
}: ActivityMetaProps) {
  return (
    <div
      className={cn(
        "space-y-1.5 text-text-muted",
        compact ? "text-[11px]" : "text-xs",
