}
import { REGISTRATION_STATUS_LABELS } from "@/features/activities/config";
import type { RegistrationStatus } from "@/features/activities/types";
import { Badge } from "@/components/ui/Badge";

const STATUS_TONES = {
  open: "success",
  upcoming: "warning",
  closed: "neutral",
} as const;

type ActivityStatusBadgeProps = {
  status: RegistrationStatus;
};

export function ActivityStatusBadge({ status }: ActivityStatusBadgeProps) {
  return (
    <Badge tone={STATUS_TONES[status]} withDot>
      {REGISTRATION_STATUS_LABELS[status]}
    </Badge>
  );
}
"use client";

import Image from "next/image";
import { useState } from "react";
import { cn } from "@/libs/cn";

const PLACEHOLDER = "/images/landing/activity-placeholder.png";

type ActivityImageProps = {
  src: string | null;
  alt: string;
  className?: string;
  sizes?: string;
};

export function ActivityImage({
  src,
  alt,
  className,
  sizes = "(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw",
}: ActivityImageProps) {
  const [failed, setFailed] = useState(false);
  const imageSrc = !src || failed ? PLACEHOLDER : src;

  return (
    <div
      className={cn(
        "relative overflow-hidden bg-primary/10",
        className,
      )}
    >
      <Image
        src={imageSrc}
        alt={alt}
        fill
        sizes={sizes}
        className="object-cover"
        onError={() => {
          if (!failed) {
            setFailed(true);
          }
        }}
      />
    </div>
  );
}
import { ActivityCard } from "@/features/activities/components/ActivityCard";
import type { LandingActivities } from "@/features/activities/types";

type ActivityGridProps = {
  activities: LandingActivities;
};

export function ActivityGrid({ activities }: ActivityGridProps) {
  const { featured, upcoming } = activities;

  if (featured.length === 0 && upcoming.length === 0) {
    return null;
  }

  if (featured.length > 0 && upcoming.length > 0) {
    return (
      <div
        data-testid="activity-grid"
        data-layout="grouped"
        className="grid gap-5 lg:grid-cols-[2fr_1fr]"
      >
        <div className="grid gap-5 sm:grid-cols-2">
          {featured.map((activity) => (
            <ActivityCard
              key={activity.id}
              activity={activity}
              variant="featured"
            />
          ))}
        </div>
        <div className="grid gap-4">
          {upcoming.map((activity) => (
            <ActivityCard
              key={activity.id}
              activity={activity}
              variant="compact"
            />
          ))}
        </div>
      </div>
    );
  }

  if (featured.length > 0) {
    return (
      <div
        data-testid="activity-grid"
        data-layout="featured-only"
        className={
          featured.length === 1
            ? "grid gap-5"
            : "grid gap-5 sm:grid-cols-2"
        }
      >
        {featured.map((activity) => (
          <ActivityCard
            key={activity.id}
            activity={activity}
            variant="featured"
          />
        ))}
      </div>
    );
  }

  return (
    <div
      data-testid="activity-grid"
      data-layout="upcoming-only"
      className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3"
    >
      {upcoming.map((activity) => (
        <ActivityCard
          key={activity.id}
          activity={activity}
          variant="featured"
        />
      ))}
    </div>
  );
}

